        guidance: 'Include identity and configuration data, not only business data; rebuilding the platform is usually the longest part of recovery.',
        controlName: 'Backup scope and scheduling', controlType: 'preventive', controlNature: 'technical',
        frequency: '{{backupFrequency}}', kpi: '% of critical systems within backup scope (target: 100%)',
